import json,glob,os,collections
out=[]
for f in sorted(glob.glob('logs/sessions/*/*.json'), key=os.path.getmtime):
    d=json.load(open(f)); r=d.get('result') or {}
    tr=r.get('trace') or []
    if not tr: continue
    th=collections.defaultdict(list)
    for t in tr:
        m=t['move']; a=t['actor']
        if a=='buyer':
            if m.get('type')=='message':
                ts=m.get('term_sheets') or []
                th[m.get('supplier_id')].append(('B',[s['terms'].get('unit_price') for s in ts]))
            else:
                th[m.get('supplier_id')].append(('B',m.get('type')))
        else:
            th[a].append(('S',m.get('terms',{}).get('unit_price'),m.get('status')))
    print(os.path.basename(f)[:20], d['case_id'], 'score',round(r.get('score') or 0,2), 'deal',(r.get('terms') or {}).get('unit_price'))
    for sid,seq in th.items():
        s=' '.join(f"S{x[1]}{'' if x[2]=='open' else '['+str(x[2])+']'}" if x[0]=='S' else f"B{x[1]}" for x in seq)
        print('   ',sid,s)
